34	function sanitizeWorksSaveFile(
35	  saveFile: Record<string, unknown> | null,
36	): Record<string, unknown> | null {
37	  if (!saveFile) return null;
38	  const sheetsByIdValue = saveFile.sheetsById;
39	  if (
40	    sheetsByIdValue == null ||
41	    typeof sheetsByIdValue !== "object" ||
42	    Array.isArray(sheetsByIdValue)
43	  ) {
44	    return saveFile;
45	  }
46	  const sheetsById = sheetsByIdValue as Record<string, unknown>;
47	  const nextSheetsById: Record<string, unknown> = {};
48	  WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
49	    if (!Object.prototype.hasOwnProperty.call(sheetsById, sheetId)) return;
50	    nextSheetsById[sheetId] = sheetsById[sheetId];
51	  });
52	  return {
53	    ...saveFile,
54	    sheetsById: nextSheetsById,
55	  };
56	}
