58	function createWorksEngine(
59	  canvasId: string,
60	  canvasElement?: HTMLCanvasElement | null,
61	): Engine {
62	  const three = WorksSceneDefinition.createThreeConfig(canvasId);
63	  return new Engine({
64	    canvasId: three.canvasId,
65	    canvasElement,
66	    camera: three.camera,
67	    cameraTarget: three.cameraTarget,
68	    renderer: three.renderer,
69	    pixelRatioMax: three.pixelRatioMax,
70	    shadowMap: three.shadowMap,
71	    renderBudget: three.renderBudget,
72	    scene: three.scene,
73	    postProcessing: three.postProcessing,
74	  });
75	}
