77	function createWorksAuthorState(engine: Engine): WorksAuthorState {
78	  const camera = engine.getCamera();
79	  const target = engine.getCameraTarget();
80	  const sceneLightObject = engine.getSceneObjectById(sceneLights) as
81	    | SceneLightsPort
82	    | null;
83	  const windowObject = engine.getObjectById(windowObj) as
84	    | {
85	        position?: { x: number; y: number; z: number };
86	        scale?: { x: number; y: number; z: number };
87	        visible?: boolean;
88	      }
89	    | null;
90	  const windowRotation = Helpers.readRotationDeg(windowObject as never);
91	  const planetObject = engine.getObjectById(planet) as
92	    | {
93	        position?: { x: number; y: number; z: number };
94	        scale?: { x: number; y: number; z: number };
95	        visible?: boolean;
96	      }
97	    | null;
98	  const planetRotation = Helpers.readRotationDeg(planetObject as never);
99	  return {
100	    camera: {
101	      position: {
102	        x: camera.position.x,
103	        y: camera.position.y,
104	        z: camera.position.z,
105	      },
106	      target: {
107	        x: target.position.x,
108	        y: target.position.y,
109	        z: target.position.z,
110	      },
111	      fov: camera.fov,
112	    },
113	    sceneLights: normalizeWorksSceneLightsState(sceneLightObject?.getState()),
114	    window: {
115	      position: {
116	        x: windowObject?.position?.x ?? 0,
117	        y: windowObject?.position?.y ?? 0,
118	        z: windowObject?.position?.z ?? 0,
119	      },
120	      rotation: {
121	        x: windowRotation.x,
122	        y: windowRotation.y,
123	        z: windowRotation.z,
124	      },
125	      scale: {
126	        x: windowObject?.scale?.x ?? 1,
127	        y: windowObject?.scale?.y ?? 1,
128	        z: windowObject?.scale?.z ?? 1,
129	      },
130	      visible: windowObject?.visible ?? true,
131	    },
132	    planet: {
133	      position: {
134	        x: planetObject?.position?.x ?? 0,
135	        y: planetObject?.position?.y ?? 0,
136	        z: planetObject?.position?.z ?? 0,
137	      },
138	      rotation: {
139	        x: planetRotation.x,
140	        y: planetRotation.y,
141	        z: planetRotation.z,
142	      },
143	      scale: {
144	        x: planetObject?.scale?.x ?? 1,
145	        y: planetObject?.scale?.y ?? 1,
146	        z: planetObject?.scale?.z ?? 1,
147	      },
148	      visible: planetObject?.visible ?? true,
149	    },
150	  };
151	}
