153	function createWorksAuthorSceneState(state: WorksAuthorState): SceneFromState {
154	  const windowPosition = state.window?.position ?? { x: 0, y: 0, z: 0 };
155	  const windowRotation = state.window?.rotation ?? { x: 0, y: 0, z: 0 };
156	  const windowScale = state.window?.scale ?? { x: 1, y: 1, z: 1 };
157	  return {
158	    camera: {
159	      position: { ...state.camera.position },
160	      fov: state.camera.fov,
161	    },
162	    cameraTarget: {
163	      position: { ...state.camera.target },
164	    },
165	    [sceneLights]: {
166	      ...state.sceneLights,
167	      ground: {
168	        position: { ...state.sceneLights.ground.position },
169	        rotation: { ...state.sceneLights.ground.rotation },
170	        scale: { ...state.sceneLights.ground.scale },
171	        visible: state.sceneLights.ground.visible,
172	      },
173	    } as Record<string, unknown>,
174	    [windowObj]: {
175	      position: { ...windowPosition },
176	      rotation: { ...windowRotation },
177	      scale: { ...windowScale },
178	      visible: state.window?.visible ?? true,
179	    } as Record<string, unknown>,
180	    [planet]: { ...state.planet } as Record<string, unknown>,
181	  };
182	}
