215	export class WorksTheatreBridge {
216	  private static readonly _statusId = "works-theatre-status";
217	  private static readonly _exportButtonId = "works-theatre-export";
218	  private static readonly _sheetSelectId = "works-theatre-sheet-select";
219	
220	  private _engine: Engine | null = null;
221	  private _objectSetup: ObjectSetup | null = null;
222	  private _controls: OrbitControls | null = null;
223	  private _authorSheetId: WorksTheatreSheetId = WORKS_THEATRE_SHEET_IDS[0] ?? "works";
224	  private readonly _sheetById = new Map<
225	    WorksTheatreSheetId,
226	    TheatreSheetPort<WorksAuthorState, WorksAuthorState>
227	  >();
228	  private readonly _objectBySheetId = new Map<
229	    WorksTheatreSheetId,
230	    TheatreObjectPort<WorksAuthorState, WorksAuthorState>
231	  >();
232	  private _unsubscribeValues: (() => void) | null = null;
233	  private _recordScrub: TheatreScrubPort<WorksAuthorState, WorksAuthorState> | null =
234	    null;
235	  private _sampling = false;
236	  private _lastSampleAt = 0;
237	  private readonly _onControlsStart = () => this._recordStart();
238	  private readonly _onControlsEnd = () => this._recordEnd();
239	  private readonly _onControlsChange = () => this._recordFrame();
240	  private readonly _onExportClick = () => void this._exportSaveFile();
241	  private readonly _onSheetChange = (event: Event) => {
242	    const select = event.currentTarget;
243	    if (!(select instanceof HTMLSelectElement)) return;
244	    this._setAuthorSheetId(select.value);
245	  };
246	
247	  async run(
248	    canvasId: string,
249	    canvasElement?: HTMLCanvasElement | null,
250	  ): Promise<void> {
251	    const engine = createWorksEngine(canvasId, canvasElement);
252	    if (!engine.init()) return;
253	    this._engine = engine;
254	    this._objectSetup = new ObjectSetup();
255	    const config = WorksSceneDefinition.createIntroPageConfig(
256	      canvasId,
257	      WorksSceneDefinition.createInitialState(
258	        createWorksAuthorSceneState(createDefaultWorksAuthorState()),
259	      ),
260	    );
261	    await this._objectSetup.init(engine, config);
262	    engine.setState(config.initialState ?? {});
263	    engine.start(() => undefined, () => undefined);
264	
265	    const renderer = engine.getRenderer() as { domElement?: HTMLCanvasElement } | null;
266	    const domElement = renderer?.domElement;
267	    if (!domElement) return;
268	    this._controls = new OrbitControls(engine.getCamera(), domElement);
269	    this._controls.target = engine.getCameraTarget().position;
270	    this._controls.enableDamping = true;
271	    this._controls.update();
272	
273	    await TheatreStudioService.ensureReady("works");
274	    TheatreStudioService.restoreUi();
275	
276	    const project = TheatreProjectSession.open<WorksAuthorState, WorksAuthorState>(
277	      WORKS_THEATRE_PROJECT_ID,
278	      {
279	        state: readWorksTheatreAuthorStateSource() ?? undefined,
280	      },
281	    );
282	    await project.ready;
283	    WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
284	      const sheet = TheatreSheetSession.open(project, sheetId);
285	      const object = sheet.object(
286	        WORKS_THEATRE_OBJECT_ID,
287	        createWorksAuthorState(engine),
288	        { reconfigure: true },
289	      );
290	      this._sheetById.set(sheetId, sheet);
291	      this._objectBySheetId.set(sheetId, object);
292	    });
293	    this._attachSheet(this._authorSheetId);
294	    this._bindControls();
295	    this._renderSheetSelector();
296	    this._renderExportButton();
297	    this._renderStatus("WORKS THEATRE READY");
298	  }
299	
300	  dispose(): void {
301	    this._controls?.removeEventListener("start", this._onControlsStart);
302	    this._controls?.removeEventListener("end", this._onControlsEnd);
303	    this._controls?.removeEventListener("change", this._onControlsChange);
304	    this._controls?.dispose();
305	    this._controls = null;
306	    this._recordScrub?.discard();
307	    this._recordScrub = null;
308	    this._unsubscribeValues?.();
309	    this._unsubscribeValues = null;
310	    TheatreStudioService.removeAuthorControl(
311	      WorksTheatreBridge._exportButtonId,
312	      "button",
313	      this._onExportClick as EventListener,
314	    );
315	    TheatreStudioService.removeAuthorControl(
316	      WorksTheatreBridge._sheetSelectId,
317	      "select",
318	      this._onSheetChange as EventListener,
319	    );
320	    TheatreStudioService.removeAuthorControl(WorksTheatreBridge._statusId, "status");
321	    this._sheetById.clear();
322	    this._objectBySheetId.clear();
323	    this._objectSetup?.dispose();
324	    this._objectSetup = null;
325	    this._engine?.dispose();
326	    this._engine = null;
327	  }
328	
329	  private _attachSheet(sheetId: WorksTheatreSheetId): void {
330	    const sheet = this._sheetById.get(sheetId);
331	    const object = this._objectBySheetId.get(sheetId);
332	    if (!sheet || !object || !this._engine) return;
333	    this._unsubscribeValues?.();
334	    this._authorSheetId = sheetId;
335	    this._unsubscribeValues = TheatrePlaybackService.bindValues(
336	      object,
337	      (values: WorksAuthorState) => {
338	        if (!this._engine) return;
339	        this._engine.setState(
340	          WorksSceneDefinition.createInitialState(
341	            createWorksAuthorSceneState(values),
342	          ),
343	        );
