421	  private _readSheetEndValues(
422	    sheetId: ContactTheatreSheetId,
423	    object: ContactTheatreObject,
424	    sequence: ContactTheatreSequence,
425	  ): ContactTheatreValue | null {
426	    const previousPosition = sequence.position;
427	    try {
428	      sequence.pause();
429	      sequence.position = this._resolveSheetEndPosition(sheetId, sequence);
430	      return this._rig.readObjectValue(object.value);
431	    } catch (_error) {
432	      return null;
433	    } finally {
434	      sequence.position = previousPosition;
435	    }
