482	    const previousPosition = currentSequence.position;
483	    const scrub = TheatreStudioService.createScrub<
484	      ContactTheatreValue,
485	      ContactTheatreProps
486	    >();
487	    currentSequence.position = 0;
488	    scrub.capture(({ set }) => {
